def dfs(node, parent, adj, leaves):
    total = 0
    for child in adj[node]:
        if child == parent:
            continue
        total += dfs(child, node, adj, leaves)
    if total + 1 == len(adj[node]):
        leaves.append(node)
    return total + 1

def solve(n, k, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u - 1].append(v - 1)
        adj[v - 1].append(u - 1)
    leaves = []
    dfs(0, -1, adj, leaves)
    moves = 0
    while leaves:
        new_leaves = []
        for i in range(0, len(leaves), k):
            group = leaves[i:i + k]
            parent = adj[group[0]][0] if len(adj[group[0]]) > 1 else group[0]
            for node in group:
                adj[parent].remove(node)
                if len(adj[parent]) == 1:
                    new_leaves.append(parent)
        leaves = new_leaves
        moves += 1
    return moves

